package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	acc := map[string]int64{}
	for sc.Scan() {
		f := strings.Fields(sc.Text())
		if len(f) == 0 {
			continue
		}
		parse := func(s string) int64 {
			v, _ := strconv.ParseInt(s, 10, 64)
			return v
		}
		switch f[0] {
		case "open":
			if len(f) < 3 {
				continue
			}
			a := parse(f[2])
			if a < 0 {
				fmt.Fprintln(w, "error: invalid amount")
			} else if _, ok := acc[f[1]]; ok {
				fmt.Fprintln(w, "error: duplicate account")
			} else {
				acc[f[1]] = a
				fmt.Fprintln(w, "ok")
			}
		case "deposit", "withdraw":
			if len(f) < 3 {
				continue
			}
			a := parse(f[2])
			if a <= 0 {
				fmt.Fprintln(w, "error: invalid amount")
			} else if b, ok := acc[f[1]]; !ok {
				fmt.Fprintln(w, "error: unknown account "+f[1])
			} else if f[0] == "deposit" {
				acc[f[1]] = b + a
				fmt.Fprintln(w, "ok")
			} else if b < a {
				fmt.Fprintln(w, "error: insufficient funds")
			} else {
				acc[f[1]] = b - a
				fmt.Fprintln(w, "ok")
			}
		case "transfer":
			if len(f) < 4 {
				continue
			}
			a := parse(f[3])
			if a <= 0 {
				fmt.Fprintln(w, "error: invalid amount")
			} else if _, ok := acc[f[1]]; !ok {
				fmt.Fprintln(w, "error: unknown account "+f[1])
			} else if _, ok := acc[f[2]]; !ok {
				fmt.Fprintln(w, "error: unknown account "+f[2])
			} else if f[1] == f[2] {
				fmt.Fprintln(w, "error: same account")
			} else if acc[f[1]] < a {
				fmt.Fprintln(w, "error: insufficient funds")
			} else {
				acc[f[1]] -= a
				acc[f[2]] += a
				fmt.Fprintln(w, "ok")
			}
		case "balance":
			if len(f) < 2 {
				continue
			}
			if b, ok := acc[f[1]]; !ok {
				fmt.Fprintln(w, "error: unknown account "+f[1])
			} else {
				fmt.Fprintln(w, b)
			}
		}
	}
	names := make([]string, 0, len(acc))
	for n := range acc {
		names = append(names, n)
	}
	sort.Strings(names)
	for _, n := range names {
		fmt.Fprintln(w, n, acc[n])
	}
}
